package dev.raf.radar;
import android.app.*;import android.graphics.Color;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;import org.json.*;
final class PointStatistics {
 interface Transport{JSONObject get(String query,String token)throws Exception;}static Transport transport=PointStatistics::request;
 final MainActivity a;final Point point;final ExecutorService worker=Executors.newSingleThreadExecutor();AlertDialog dialog;LinearLayout body;TextView status,retry;boolean busy,closed;
 PointStatistics(MainActivity a,Point p){this.a=a;try{point=Point.from(p.json());}catch(Exception e){throw new IllegalArgumentException(e);}}
 static void show(MainActivity a,Point p){new PointStatistics(a,p).show();}
 void show(){LinearLayout root=a.column();root.setPadding(a.dp(18),a.dp(16),a.dp(18),a.dp(12));root.setBackground(Appearance.lineage(a)?Appearance.frame(a,false):a.shape(a.surface,22));LinearLayout header=a.row();TextView title=a.heading(point.name,22);title.setMaxLines(1);title.setEllipsize(android.text.TextUtils.TruncateAt.END);header.addView(title,new LinearLayout.LayoutParams(0,-2,1));TextView close=a.primary("×",false,()->dialog.dismiss());close.setContentDescription("Закрыть статистику точки");header.addView(close,new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));root.addView(header);
  root.addView(a.text(new java.text.SimpleDateFormat("EEEE, d MMMM",new Locale("ru")).format(new Date())+" · Эконом, ₽",12,a.muted));status=a.text("Загружаем историю точки…",13,a.muted);status.setPadding(0,a.dp(12),0,a.dp(8));root.addView(status);
  ScrollView scroll=new ScrollView(a);body=a.column();scroll.addView(body);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));retry=a.primary("Обновить",false,this::load);root.addView(retry,new LinearLayout.LayoutParams(-1,a.dp(46)));
  TextView note=a.text("История этой точки за 12 недель, в радиусе 100 м. Среднее по таким дням недели, не гарантия будущей цены. Пропуски — нет наблюдений.",11,a.muted);note.setPadding(0,a.dp(10),0,0);root.addView(note);
  dialog=new AlertDialog.Builder(a).setView(root).create();dialog.setOnDismissListener(d->{closed=true;worker.shutdownNow();});dialog.setOnShowListener(d->{dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);dialog.getWindow().setLayout(Math.min(a.getResources().getDisplayMetrics().widthPixels-a.dp(24),a.dp(560)),Math.min((int)(a.getResources().getDisplayMetrics().heightPixels*.86f),a.dp(720)));});dialog.show();load();
 }
 void load(){if(busy||closed)return;String token=AccountClient.session(a.store);if(token==null){status.setText("Войдите в Sense PRO, чтобы увидеть историю");return;}busy=true;retry.setEnabled(false);status.setText("Загружаем историю точки…");String query="sourcePoint="+StatisticsPanel.UriEncode(point.id)+"&lat="+point.lat+"&lon="+point.lon+"&timezone="+StatisticsPanel.UriEncode(TimeZone.getDefault().getID());worker.execute(()->{JSONObject result=null;try{result=transport.get(query,token);}catch(Exception e){Diagnostics.error("statistics","point_history_failed",e,0,-1,-1,null);}JSONObject received=result;a.runOnUiThread(()->{if(closed||a.isDestroyed())return;busy=false;retry.setEnabled(true);if(received==null){status.setText("Не удалось загрузить историю. Проверьте соединение и повторите.");return;}render(received);});});}
 void render(JSONObject data){body.removeAllViews();int days=data.optInt("historyDays",0);status.setText((days==0?"Истории за этот день недели пока нет":("История: "+days+" "+daysWord(days)+(days<3?" · мало данных":"")))+"\n"+data.optString("timezone",TimeZone.getDefault().getID()));LinearLayout labels=a.row();labels.addView(a.text("Время",11,a.muted),new LinearLayout.LayoutParams(0,-2,1));labels.addView(a.text("Обычно",11,StatisticsPanel.SCARLET),new LinearLayout.LayoutParams(0,-2,2));TextView todayLabel=a.text("Сегодня",11,StatisticsPanel.PURPLE);todayLabel.setGravity(Gravity.END);labels.addView(todayLabel,new LinearLayout.LayoutParams(0,-2,1));body.addView(labels);
  JSONArray slots=data.optJSONArray("slots");for(int hour=0;hour<24;hour++){JSONObject v=slots==null?null:slots.optJSONObject(hour);LinearLayout row=a.row();row.setPadding(a.dp(6),a.dp(8),a.dp(6),a.dp(8));if(hour==Calendar.getInstance().get(Calendar.HOUR_OF_DAY))row.setBackground(Appearance.lineage(a)?Appearance.frame(a,false):a.shape(a.bg,10));TextView time=a.text(String.format(Locale.US,"%02d:00",hour),13,a.fg);row.addView(time,new LinearLayout.LayoutParams(0,-2,1));LinearLayout historical=a.column();historical.addView(a.heading(value(v,"historical"),16));int n=v==null?0:v.optInt("historyDays");String range=n==0?"Нет истории":n+" "+daysWord(n);if(v!=null&&n>1&&!v.isNull("low")&&!v.isNull("high")&&v.optInt("low")!=v.optInt("high"))range+=" · "+v.optInt("low")+"–"+v.optInt("high")+" ₽";historical.addView(a.text(range,10,a.muted));row.addView(historical,new LinearLayout.LayoutParams(0,-2,2));TextView actual=a.text(value(v,"actual"),15,StatisticsPanel.PURPLE);actual.setGravity(Gravity.END);row.addView(actual,new LinearLayout.LayoutParams(0,-2,1));body.addView(row);View line=new View(a);line.setBackgroundColor(0x223F444C);body.addView(line,new LinearLayout.LayoutParams(-1,a.dp(1)));}
  TextView explanation=a.text("Диапазон — средние значения разных дней. Каждый день имеет одинаковый вес.",11,a.muted);explanation.setPadding(0,a.dp(12),0,a.dp(8));body.addView(explanation);
 }
 static String daysWord(int n){return n%10==1&&n%100!=11?"день":n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?"дня":"дней";}
 static String value(JSONObject v,String key){if(v==null||v.isNull(key)||!v.has(key))return "—";int n=v.optInt(key);return (n>0?"+":"")+n+" ₽";}
 static JSONObject request(String query,String token)throws Exception{long start=SystemClock.elapsedRealtime();HttpURLConnection c=(HttpURLConnection)new URL("https://radar-presence.vercel.app/api/point-statistics?"+query).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(20000);c.setRequestProperty("Authorization","Bearer "+token);c.setInstanceFollowRedirects(false);try{int status=c.getResponseCode();Diagnostics.record("statistics","point_history_http",status==200?"info":"error",null,status,SystemClock.elapsedRealtime()-start,-1,null);if(status!=200)throw new IOException("point_history_http_"+status);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[4096];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>64000)throw new IOException("point_history_size");out.write(buffer,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
}
